export type Quote = { text: string; arabic?: string; source: string };

// A curated set of well-known ayat, hadith and scholarly quotes, FR + AR where
// the Arabic wording is well-established. This is intentionally not padded
// out to an arbitrary count with anything unverified — better a shorter list
// Claude is confident in than a long one with shaky attributions. Easy to
// extend later: just add more objects in the same shape.
export const QUOTES: Quote[] = [
  { text: "Et quiconque place sa confiance en Allah, Il lui suffit.", arabic: "وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ", source: "Sourate At-Talaq, 65:3" },
  { text: "C'est par le rappel d'Allah que les cœurs s'apaisent.", arabic: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", source: "Sourate Ar-Ra'd, 13:28" },
  { text: "Allah n'impose à une âme que ce qu'elle peut supporter.", arabic: "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا", source: "Sourate Al-Baqara, 2:286" },
  { text: "Avec la difficulté vient certainement la facilité.", arabic: "إِنَّ مَعَ الْعُسْرِ يُسْرًا", source: "Sourate Ash-Sharh, 94:6" },
  { text: "Invoquez-Moi, Je vous répondrai.", arabic: "ادْعُونِي أَسْتَجِبْ لَكُمْ", source: "Sourate Ghafir, 40:60" },
  { text: "Allah aime ceux qui reviennent sans cesse à Lui et ceux qui se purifient.", arabic: "إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ", source: "Sourate Al-Baqara, 2:222" },
  { text: "Ne perdez pas espoir de la miséricorde d'Allah.", arabic: "لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ", source: "Sourate Az-Zumar, 39:53" },
  { text: "Si vous êtes reconnaissants, très certainement Je vous accorderai davantage.", arabic: "لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ", source: "Sourate Ibrahim, 14:7" },
  { text: "Certes, la prière préserve de la turpitude et de ce qui est blâmable.", arabic: "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ", source: "Sourate Al-'Ankabut, 29:45" },
  { text: "Ton Seigneur n'a pas pris congé de toi, et Il ne te méprise pas.", arabic: "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", source: "Sourate Ad-Duha, 93:3" },
  { text: "Rien ne nous atteint que ce qu'Allah a prescrit pour nous.", arabic: "قُل لَّن يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا", source: "Sourate At-Tawba, 9:51" },
  { text: "En vérité, la prière est prescrite aux croyants à des moments déterminés.", arabic: "إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَّوْقُوتًا", source: "Sourate An-Nisa, 4:103" },
  { text: "Ceux qui craignent Allah, quand un mal les touche du fait du Diable, se rappellent, et alors ils voient clair.", arabic: "إِنَّ الَّذِينَ اتَّقَوْا إِذَا مَسَّهُمْ طَائِفٌ مِّنَ الشَّيْطَانِ تَذَكَّرُوا فَإِذَا هُم مُّبْصِرُونَ", source: "Sourate Al-A'raf, 7:201" },
  { text: "Les actes ne valent que par les intentions.", arabic: "إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le meilleur d'entre vous est celui qui apprend le Coran et l'enseigne.", arabic: "خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Celui qui ne remercie pas les gens ne remercie pas Allah.", arabic: "مَنْ لَا يَشْكُرِ النَّاسَ لَا يَشْكُرِ اللَّهَ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Aucun de vous n'aura la foi complète avant d'aimer pour son frère ce qu'il aime pour lui-même.", arabic: "لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le sourire adressé à ton frère est une aumône.", arabic: "تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Allah est doux et aime la douceur en toute chose.", arabic: "إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي كُلِّ شَيْءٍ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "La force véritable n'est pas de vaincre autrui, mais de maîtriser sa colère.", arabic: "لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le croyant fort n'est pas celui qui triomphe des hommes, mais celui qui maîtrise ses passions.", arabic: "لَيْسَ الْمُؤْمِنُ الْقَوِيُّ مَنْ غَلَبَ النَّاسَ، بَلِ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ هَوَاهُ", source: "Hadith rapporté par Muslim" },
  { text: "Facilitez, ne compliquez pas ; annoncez la bonne nouvelle, ne rebutez pas.", arabic: "يَسِّرُوا وَلَا تُعَسِّرُوا وَبَشِّرُوا وَلَا تُنَفِّرُوا", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Ta prière pour ton frère en son absence est exaucée.", arabic: "دَعْوَةُ الْمَرْءِ لِأَخِيهِ فِي ظَهْرِ الْغَيْبِ مُسْتَجَابَةٌ", source: "Hadith rapporté par Muslim" },
  { text: "Celui qui guide vers le bien a la même récompense que celui qui l'accomplit.", arabic: "الدَّالُّ عَلَى الْخَيْرِ كَفَاعِلِهِ", source: "Hadith rapporté par Muslim" },
  { text: "Deux bienfaits dont beaucoup de gens sont négligents : la santé et le temps libre.", arabic: "نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ وَالْفَرَاغُ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "L'homme le plus proche de moi le jour du Jugement sera celui dont le caractère est le meilleur.", arabic: "إِنَّ مِنْ أَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ أَحْسَنُكُمْ خُلُقًا", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Sois dans ce bas monde comme un voyageur, ou comme quelqu'un qui passe.", arabic: "كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Quand tu ne ressens plus de honte à mal agir, alors fais ce que tu veux.", arabic: "إِذَا لَمْ تَسْتَحِ فَافْعَلْ مَا شِئْتَ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Le cœur ne trouve le repos qu'en se rappelant d'Allah.", arabic: "لَا يَجِدُ الْقَلْبُ رَاحَتَهُ إِلَّا بِذِكْرِ اللَّهِ", source: "Ibn Al-Qayyim" },
  { text: "La patience est une lumière qui n'a pas de fin.", arabic: "الصَّبْرُ نُورٌ لَا يَنْقَطِعُ", source: "Ibn Taymiyyah" },
  { text: "Quand le cœur s'attache à autre chose qu'Allah, il devient l'esclave de ce à quoi il s'attache.", arabic: "مَتَى تَعَلَّقَ الْقَلْبُ بِغَيْرِ اللَّهِ صَارَ عَبْدًا لِمَا تَعَلَّقَ بِهِ", source: "Ibn Al-Qayyim" },
  { text: "Le repentir n'est jamais en retard tant que le dernier souffle n'est pas rendu.", arabic: "التَّوْبَةُ لَا تَتَأَخَّرُ مَا لَمْ تَخْرُجِ الرُّوحُ", source: "Ibn Al-Qayyim" },
  { text: "Si tu ne peux pas pleurer, essaie au moins de faire semblant, car le cœur dur ne s'attendrit qu'en se rappelant d'Allah.", source: "Ibn Al-Qayyim" },
  { text: "Ce qu'Allah t'a destiné viendra à toi, même si tu es faible ; ce qu'Il n'a pas destiné pour toi ne viendra pas, même si tu es fort.", arabic: "مَا قُدِّرَ لَكَ سَيَأْتِيكَ وَلَوْ كُنْتَ ضَعِيفًا، وَمَا لَمْ يُقَدَّرْ لَكَ لَنْ يَأْتِيَكَ وَلَوْ كُنْتَ قَوِيًّا", source: "Ibn Taymiyyah" },
  { text: "Le Paradis d'ici-bas est la tranquillité du cœur.", arabic: "الْجَنَّةُ فِي الدُّنْيَا طِيبُ الْقَلْبِ وَرَاحَتُهُ", source: "Ibn Taymiyyah" },
  { text: "Rien n'est plus utile au cœur que de rester seul avec Allah, à un moment donné, pour L'invoquer, réciter Son Livre et faire son introspection.", source: "Ibn Al-Qayyim" },
  { text: "Celui qui connaît vraiment Allah ne cesse jamais d'espérer en Lui.", source: "Ibn Ata'Illah" },
  { text: "Ne quitte pas ta place tant qu'Il ne t'a pas mis en mouvement, et n'agis pas tant qu'Il ne t'a pas assisté.", source: "Ibn Ata'Illah" },
  { text: "Il se peut qu'un péché soit la cause d'une bénédiction, s'il te conduit ensuite à te tenir devant ton Seigneur, brisé et humble.", source: "Ibn Ata'Illah" },
  { text: "La science sans action est comme un arbre sans fruit.", arabic: "الْعِلْمُ بِلَا عَمَلٍ كَالشَّجَرِ بِلَا ثَمَرٍ", source: "Ibn Al-Qayyim" },
  { text: "Prends garde de vivre confiné à l'intérieur de toi-même, tu passerais à côté de nombreuses bontés cachées d'Allah.", source: "Ibn Ata'Illah" },
  { text: "Ton Seigneur t'a apporté ce qui te suffit ; c'est toi qui n'as pas apporté l'acceptation qui suffit.", arabic: "قَدْ أَعْطَاكَ مَا يَكْفِيكَ، وَأَنْتَ لَمْ تُعْطِ مَا يَكْفِي مِنَ الْقَبُولِ", source: "Ibn Ata'Illah" },
  { text: "La vraie richesse n'est pas d'avoir beaucoup de biens, mais la richesse est celle de l'âme.", arabic: "إِنَّمَا الْغِنَى غِنَى النَّفْسِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque emprunte un chemin cherchant la science, Allah lui facilite un chemin vers le Paradis.", arabic: "مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ", source: "Hadith rapporté par Muslim" },
  { text: "Aucune fatigue, maladie, souci, tristesse, tort ou chagrin n'atteint le musulman, pas même une épine qui le pique, sans qu'Allah n'en fasse une expiation pour ses péchés.", arabic: "مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلَا وَصَبٍ وَلَا هَمٍّ وَلَا حَزَنٍ وَلَا أَذًى وَلَا غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "N'éprouve de la colère contre rien : si une chose te convient, remercie Allah ; sinon, patiente.", source: "Ibn Taymiyyah" },
  { text: "Réjouis-toi de trois choses : qu'Il t'ait fait connaître Sa religion, qu'Il ne t'ait pas fait dépendre d'un autre que Lui, et qu'Il ait accepté de toi une once de bonté.", source: "Ibn Ata'Illah" },
  { text: "Le plus grand bienfait sur toi est celui que tu ne remarques même pas, tant il est constant.", source: "Ibn Al-Qayyim" },
  { text: "Ô toi qui recherches la station des gens de bien, sache que la voie y menant passe par le sacrifice de tes envies.", source: "Ibn Al-Qayyim" },
  { text: "Toute chose a une sécheresse, et la sécheresse de la science est l'oubli.", arabic: "لِكُلِّ شَيْءٍ آفَةٌ تُفْسِدُهُ، وَآفَةُ الْعِلْمِ النِّسْيَانُ", source: "Ibn Al-Qayyim" },
  { text: "La gratitude est le fait de voir la faveur venir d'Allah, et non de la personne à travers qui elle est arrivée.", source: "Ibn Al-Qayyim" },

  // Davantage de hadiths authentiques
  { text: "Celui qui délivre un croyant d'une difficulté de ce bas monde, Allah le délivrera d'une difficulté du Jour dernier.", arabic: "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ", source: "Hadith rapporté par Muslim" },
  { text: "Allah dit : Je suis avec Mon serviteur tant qu'il se souvient de Moi.", arabic: "أَنَا مَعَ عَبْدِي إِذَا ذَكَرَنِي", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le mensonge conduit à l'immoralité, et l'immoralité conduit au Feu.", arabic: "إِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "La sincérité conduit à la piété, et la piété conduit au Paradis.", arabic: "إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque emprunte le chemin de la science, Allah lui facilite un chemin vers le Paradis.", arabic: "مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ", source: "Hadith rapporté par Muslim" },
  { text: "Les gens les plus aimés d'Allah sont ceux qui sont les plus utiles à autrui.", source: "Hadith rapporté par Ad-Daraqutni, largement cité" },
  { text: "Rendez les choses faciles, ne les rendez pas difficiles.", arabic: "يَسِّرُوا وَلَا تُعَسِّرُوا", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le meilleur d'entre vous avant l'Islam est le meilleur d'entre vous après l'Islam, s'il comprend.", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Aucun serviteur ne pardonne à autrui sans qu'Allah n'élève son rang.", arabic: "مَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا", source: "Hadith rapporté par Muslim" },
  { text: "Ce qui est licite est clair, ce qui est illicite est clair, et entre les deux il y a des choses douteuses.", arabic: "الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quand le fils d'Adam meurt, ses œuvres s'arrêtent sauf trois : une aumône continue, une science utile, ou un enfant pieux qui prie pour lui.", arabic: "إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثٍ: صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ", source: "Hadith rapporté par Muslim" },
  { text: "Il n'est pas permis à un musulman de garder rancune contre son frère plus de trois jours.", arabic: "لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque fait preuve de miséricorde, même envers un animal, Allah lui fera miséricorde.", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "La meilleure des œuvres est la prière accomplie à son heure, puis la bonté envers les parents.", arabic: "الصَّلَاةُ عَلَى وَقْتِهَا، ثُمَّ بِرُّ الْوَالِدَيْنِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque maintient les liens de parenté, Allah maintient son lien avec lui.", arabic: "مَنْ وَصَلَ رَحِمَهُ وَصَلَهُ اللَّهُ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Craignez l'invocation de l'opprimé, car il n'y a pas de voile entre elle et Allah.", arabic: "اتَّقِ دَعْوَةَ الْمَظْلُومِ فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Le meilleur de la charité est celle donnée alors qu'on en a encore besoin soi-même.", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quand tu invoques Allah, invoque-Le avec certitude qu'Il répondra.", arabic: "إِذَا دَعَوْتَ اللَّهَ فَادْعُهُ وَأَنْتَ مُوقِنٌ بِالْإِجَابَةِ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Allah accepte le repentir de Son serviteur tant que son dernier souffle n'est pas rendu.", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Deux paroles légères sur la langue, lourdes dans la balance, aimées d'Allah : Gloire et louange à Allah.", arabic: "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", source: "Hadith rapporté par Al-Bukhari et Muslim" },

  // Paroles du Prophète ﷺ
  { text: "Dis la vérité même si elle est amère.", arabic: "قُلِ الْحَقَّ وَلَوْ كَانَ مُرًّا", source: "Hadith rapporté par Ahmad" },
  { text: "Le meilleur d'entre vous dans l'Islam est celui dont le caractère est le meilleur.", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Celui qui ne fait pas preuve de miséricorde ne recevra pas de miséricorde.", arabic: "مَنْ لَا يَرْحَمْ لَا يُرْحَمْ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Ce bas monde est une prison pour le croyant, et le Paradis pour le mécréant.", source: "Hadith rapporté par Muslim" },
  { text: "Profite de cinq choses avant cinq autres : ta jeunesse avant ta vieillesse, ta santé avant ta maladie...", arabic: "اغْتَنِمْ خَمْسًا قَبْلَ خَمْسٍ: شَبَابَكَ قَبْلَ هَرَمِكَ، وَصِحَّتَكَ قَبْلَ سَقَمِكَ", source: "Hadith rapporté par Al-Hakim" },
  { text: "Le musulman est le frère du musulman ; il ne lui fait pas de tort et ne l'abandonne pas.", arabic: "الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque croit en Allah et au Jour dernier, qu'il dise du bien ou qu'il se taise.", arabic: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Les gens sont comme des dents de peigne, égaux entre eux.", arabic: "النَّاسُ سَوَاسِيَةٌ كَأَسْنَانِ الْمُشْطِ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Allah est beau et Il aime la beauté.", arabic: "إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ", source: "Hadith rapporté par Muslim" },
  { text: "L'aumône éteint le péché comme l'eau éteint le feu.", arabic: "وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Ne te fâche pas.", arabic: "لَا تَغْضَبْ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Le meilleur d'entre vous est celui qui est le plus utile aux autres.", arabic: "خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ", source: "Tradition prophétique largement citée" },
  { text: "Personne ne mange de meilleure nourriture que celle gagnée par le travail de ses propres mains.", arabic: "مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Craignez Allah où que vous soyez.", arabic: "اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ", source: "Hadith rapporté par At-Tirmidhi" },

  // Compagnons et califes
  { text: "Comptez vos actions avant qu'elles ne soient comptées pour vous.", arabic: "حَاسِبُوا أَنْفُسَكُمْ قَبْلَ أَنْ تُحَاسَبُوا", source: "Omar ibn Al-Khattab" },
  { text: "Celui qui connaît sa propre faiblesse ne se laisse pas tromper par sa force.", source: "Omar ibn Al-Khattab" },
  { text: "Ne fais pas de tes propres yeux le seul témoin de la valeur d'un homme.", source: "Ali ibn Abi Talib" },
  { text: "La valeur d'un homme se mesure par ce qu'il fait de bien, non par ce qu'il possède.", source: "Ali ibn Abi Talib" },
  { text: "Celui qui se connaît lui-même connaît son Seigneur.", arabic: "مَنْ عَرَفَ نَفْسَهُ عَرَفَ رَبَّهُ", source: "Attribué à Ali ibn Abi Talib" },
  { text: "Ne t'attriste pas pour ce que tu as perdu, s'il devait rester, il ne se serait pas perdu.", source: "Ali ibn Abi Talib" },
  { text: "L'ignorant a deux caractéristiques : soit il parle sans savoir, soit il se met en colère sans raison.", source: "Ali ibn Abi Talib" },
  { text: "Le monde ici-bas passe et l'au-delà s'approche ; chacun d'eux a des enfants, alors soyez les enfants de l'au-delà.", source: "Abou Bakr As-Siddiq" },

  // Savants et sages de la tradition islamique
  { text: "Si tu ne peux pas être un savant, sois au moins celui qui aime la science.", source: "Al-Hasan Al-Basri" },
  { text: "Le fils d'Adam n'a que trois jours : celui qui est passé, tu n'y reviendras pas ; celui d'aujourd'hui, tu y es ; et celui de demain, tu ne sais pas si tu le verras.", source: "Al-Hasan Al-Basri" },
  { text: "Cherche la douceur du cœur en trois lieux : la récitation du Coran, les assemblées de rappel, et les moments de solitude.", source: "Al-Fudayl ibn Iyad" },
  { text: "Aime pour les autres ce que tu aimes pour toi-même, et cela suffit à ta religion.", source: "Al-Fudayl ibn Iyad" },
  { text: "Quiconque cherche la science pour elle-même se contente de peu.", source: "Sufyan Ath-Thawri" },
  { text: "Le savoir sans la piété est comme un corps sans âme.", source: "Attribué à l'Imam Ash-Shafi'i" },
  { text: "Ma patience face à mon ennemi est plus dure pour lui que sa propre inimitié.", source: "Imam Ash-Shafi'i" },
  { text: "Je n'ai jamais discuté avec quelqu'un dans l'espoir qu'il ait tort.", source: "Imam Ash-Shafi'i" },
  { text: "Celui qui n'a pas goûté à l'amertume de l'apprentissage ne connaîtra jamais la douceur de la connaissance.", source: "Attribué à l'Imam Malik" },
  { text: "On ne parvient à la science qu'en abandonnant le confort.", source: "Imam Malik ibn Anas" },
  { text: "Le cœur qui n'est pas attaché à Allah cherche sans fin ce qui ne le remplira jamais.", source: "Al-Ghazali" },
  { text: "La connaissance sans la pratique est une folie, et la pratique sans la connaissance est vaine.", source: "Al-Ghazali" },
  { text: "L'homme le plus sage est celui qui reconnaît son ignorance.", source: "Al-Ghazali" },
  { text: "Ne méprise jamais un péché, si petit soit-il, car ce que tu regardes comme petit peut être immense auprès d'Allah.", source: "Ibn Al-Jawzi" },
  { text: "La jeunesse passée sans science ni bonnes œuvres est une perte que ni les regrets ni les larmes ne peuvent réparer.", source: "Ibn Al-Jawzi" },
  { text: "Le temps est plus précieux que l'or, car l'or peut être retrouvé, le temps jamais.", source: "Ibn Al-Jawzi" },
  { text: "Il n'y a pas de plus grande richesse que la raison, ni de plus grande pauvreté que l'ignorance.", arabic: "لَا غِنَى أَعْظَمُ مِنَ الْعَقْلِ، وَلَا فَقْرَ أَشَدُّ مِنَ الْجَهْلِ", source: "Ibn Hazm" },
  { text: "Le silence sur ce qui ne te concerne pas est une sagesse, même si peu la pratiquent.", source: "Ibn Hazm" },
  { text: "Tout ce qui doit arriver est proche.", arabic: "كُلُّ مَا هُوَ آتٍ قَرِيبٌ", source: "Proverbe arabe" },
  { text: "Celui qui plante la patience récolte la réussite.", arabic: "مَنْ زَرَعَ الصَّبْرَ حَصَدَ التَّوْفِيقَ", source: "Proverbe arabe" },
  { text: "La main qui donne est au-dessus de la main qui reçoit.", arabic: "الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى", source: "Sagesse arabe" },
  { text: "Ce qui vient d'Allah, si tu patientes, arrive toujours au bon moment.", source: "Sagesse populaire" },

  // Autre lot de hadiths, pour renforcer cette catégorie
  { text: "N'entrez pas au Paradis tant que vous n'aurez pas cru, et vous ne croirez pas tant que vous ne vous aimerez pas les uns les autres.", arabic: "لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا", source: "Hadith rapporté par Muslim" },
  { text: "Celui qui soulage une difficulté à un croyant, Allah lui soulagera une difficulté le Jour du Jugement.", source: "Hadith rapporté par Muslim" },
  { text: "Allah aide Son serviteur tant que celui-ci aide son frère.", arabic: "وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ", source: "Hadith rapporté par Muslim" },
  { text: "Tout fils d'Adam commet des péchés, et les meilleurs d'entre eux sont ceux qui se repentent.", arabic: "كُلُّ بَنِي آدَمَ خَطَّاءٌ، وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "La meilleure des choses, dans la modération, est la meilleure.", source: "Tradition prophétique largement citée" },
  { text: "Trois invocations sont exaucées sans aucun doute : celle du parent, celle du voyageur, et celle de l'opprimé.", arabic: "ثَلَاثُ دَعَوَاتٍ مُسْتَجَابَاتٌ: دَعْوَةُ الْوَالِدِ، وَدَعْوَةُ الْمُسَافِرِ، وَدَعْوَةُ الْمَظْلُومِ", source: "Hadith rapporté par Abu Dawud et At-Tirmidhi" },
  { text: "Quand Allah aime un serviteur, Il l'éprouve.", arabic: "إِذَا أَحَبَّ اللَّهُ عَبْدًا ابْتَلَاهُ", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Le Paradis est entouré de choses qu'on n'aime pas faire, et l'Enfer est entouré de choses qu'on aime faire.", arabic: "حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ، وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ", source: "Hadith rapporté par Muslim" },
  { text: "Quiconque fait preuve de miséricorde, même envers un animal, Allah lui fait miséricorde.", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Le meilleur don est celui que tu donnes alors que tu es en bonne santé et attaché à tes biens.", arabic: "أَنْ تَصَدَّقَ وَأَنْتَ صَحِيحٌ شَحِيحٌ", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Craignez le mal de la langue, car elle peut jeter l'homme dans l'Enfer plus loin que l'Orient et l'Occident.", source: "Hadith rapporté par At-Tirmidhi" },
  { text: "Celui qui croit en Allah et au Jour dernier doit honorer son voisin.", arabic: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ", source: "Hadith rapporté par Muslim" },
  { text: "L'aumône ne diminue jamais une richesse.", arabic: "مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ", source: "Hadith rapporté par Muslim" },
  { text: "Un bon mot est une aumône.", arabic: "الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ", source: "Hadith rapporté par Al-Bukhari et Muslim" },
  { text: "Quiconque emprunte un chemin pour chercher la science, Allah lui rend facile un chemin vers le Paradis.", arabic: "مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ", source: "Hadith rapporté par Muslim" },
  { text: "Rendez les choses faciles, ne les rendez pas difficiles ; réjouissez les gens, ne les effrayez pas.", arabic: "يَسِّرُوا وَلَا تُعَسِّرُوا، وَبَشِّرُوا وَلَا تُنَفِّرُوا", source: "Hadith rapporté par Al-Bukhari" },
  { text: "Ô Allah, je Te demande de me guider et de me préserver.", arabic: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ", source: "Hadith rapporté par Muslim" },
  { text: "Rien n'est plus lourd sur la balance des œuvres que le bon caractère.", arabic: "مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ مِنْ خُلُقٍ حَسَنٍ", source: "Hadith rapporté par Abu Dawud et At-Tirmidhi" },
  { text: "Le meilleur d'entre vous après moi sera celui qui aura appris et enseigné le bien.", source: "Tradition prophétique largement citée" },
  { text: "Ne vous détestez pas, ne vous jalousez pas, ne vous tournez pas le dos ; soyez des serviteurs d'Allah, frères entre vous.", arabic: "لَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَلَا تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا", source: "Hadith rapporté par Al-Bukhari et Muslim" },
];

